# Datalog program to find users with no access to any resource

# Load facts from CSV files
import "grant.csv" as grant(group, role)
import "includes.csv" as includes(role, included_role)
import "member.csv" as member(user, group)
import "permit.csv" as permit(role, resource, action)
import "revoked.csv" as revoked(user, resource)

# Compute all roles a user has, including through inclusion
user_roles(user, role) :- grant(group, role), member(user, group).
user_roles(user, included_role) :- includes(role, included_role), user_roles(user, role).

# Compute all resources a user has access to
user_resources(user, resource) :- permit(role, resource, _), user_roles(user, role).
user_resources(user, resource) :- revoked(user, resource).

